query GetDataLogs($paging: PagingInput, $filter: DataLogFilterInput, $sorting: DataLogSortingInput) {
  dataLog(sorting: $sorting, paging: $paging, filter: $filter) {
    paging {
      count
      __typename
    }
    dataLogs {
      id
      dataSource
      metadata
      fileName
      status
      summary
      detail
      errorSummary
      keyCount
      certificateCount
      sourceIdentifier
      runAt
      duration
      addedAt
      addedBy {
        id
        humanName
        __typename
      }
      lastModified
      __typename
    }
    __typename
  }
}
